// Match test for the committed genoffice tool-schema file (G6-09 W10, G7-12 residual R2, Q4).
//
//   node --test scripts/office/g5g6g7/genoffice-tool-schemas.test.mjs
//
// docs/office/g5g6g7/genoffice-tool-schemas.json is generated by the fork's extractor
// (`--emit-schemas`, see genoffice-tool-schemas.README.md) at the same rev as the extract block of
// docs/office/g5g6g7/genoffice-tools.md. Like the G7-06 extractor check, this test does not run the extractor: it
// holds the committed file to the committed block (same rev, same tools per module) and to the harness that reads it
// (holdout-backend.mjs, `--tool-schemas` semantics), so a re-pin of the table without a regenerated file fails here.

import assert from 'node:assert/strict';
import crypto from 'node:crypto';
import fs from 'node:fs';
import path from 'node:path';
import test from 'node:test';
import { fileURLToPath } from 'node:url';

import { committedBlockLines, parseExtractBlock } from './g7-06/extractor-check.mjs';
import { isUnresolvedSchemaCell } from '../instruction-pack-tools.mjs';
import { frameToolCounts, offeredTools, TOOL_OPS, toolCatalogue, toolSurface } from './holdout-backend.mjs';

const repoRoot = path.resolve(path.dirname(fileURLToPath(import.meta.url)), '../../..');
const SCHEMAS_FILE = path.join(repoRoot, 'docs/office/g5g6g7/genoffice-tool-schemas.json');
const TOOLS_DOC = path.join(repoRoot, 'docs/office/g5g6g7/genoffice-tools.md');
const MODULES = ['docs', 'sheets', 'slides', 'pdf', 'markdown', 'html'];
const RUNTIME_MARK = '[generated at runtime]';

// Tools whose description the frame builds by calling product code at runtime (opNames(), buildOpsGuide(), ...). The
// file offers them with the real inputSchema and the literal description text plus the runtime marker. A new entry
// here is a decision (the holdout then runs that tool with a reduced description): it must be reviewed, not absorbed.
const PARTIAL_DESCRIPTION_TOOLS = [
  'docs/apply_ops',
  'markdown/apply_ops',
  'pdf/apply_ops',
  'sheets/load_guide',
  'slides/apply_ops',
  'slides/load_guide',
];

// Tools whose block cell is the documented `unresolved:<reason>` form: the extractor cannot resolve the schema
// statically, so the block carries no hash and the file lists the tool in the catalogue without a schema instead of
// offering it to a model. Since G6-09d (`3e4e9b71f`) folds parameterised self-recursive arrows (`nodeSchema(maxDepth)`),
// `docs/generate_mindmap` and `markdown/generate_mindmap` resolve (`ad838ec1…`) and this list is empty: any unresolved
// row in the block, or any entry that is not offered, fails below.
const UNRESOLVED_SCHEMA_TOOLS = [];
const MINDMAP_SCHEMA_SHA256 = 'ad838ec1782297153a2f798b110c62ef30e050ee6656615f7d4ff6a7f9c925e0';

const schemaBytes = fs.readFileSync(SCHEMAS_FILE);
const file = JSON.parse(schemaBytes.toString('utf8'));
const block = committedBlockLines(fs.readFileSync(TOOLS_DOC, 'utf8'));
const committed = parseExtractBlock(block);
const sha256Hex = (value) => crypto.createHash('sha256').update(value).digest('hex');

const canonical = (value) => {
  if (value === null || typeof value !== 'object') return JSON.stringify(value);
  if (Array.isArray(value)) return `[${value.map(canonical).join(',')}]`;
  return `{${Object.keys(value)
    .sort()
    .map((k) => `${JSON.stringify(k)}:${canonical(value[k])}`)
    .join(',')}}`;
};

const namesByModule = (rows) => {
  const out = {};
  for (const module of MODULES) out[module] = [];
  for (const row of rows) if (out[row.module]) out[row.module].push(row.tool ?? row.name);
  for (const module of MODULES) out[module].sort();
  return out;
};

/** The block rows whose cell is the documented unresolved form, as `module/tool`, sorted. */
const unresolvedKeys = (rows) => rows.filter((row) => isUnresolvedSchemaCell(row.hash)).map((row) => `${row.module}/${row.tool}`).sort();

/** The names a module array may offer: every block row of the module whose cell is a resolved hash. */
const offeredNamesByModule = (rows) => {
  const out = {};
  for (const module of MODULES) out[module] = rows.filter((row) => row.module === module && !isUnresolvedSchemaCell(row.hash)).map((row) => row.tool).sort();
  return out;
};

/** The module arrays of a schema file, keyed by module. */
const moduleArraysOf = (schemaFile) => Object.fromEntries(MODULES.map((module) => [module, schemaFile[module]]));

/**
 * The unresolved cell is allowed only as the `tableHash` of a withheld entry: one finding (a string) per violation —
 * a tool a model is offered carrying the literal, a catalogue entry outside `withheld` carrying it anywhere, a
 * withheld entry whose cell is not the documented `unresolved:<reason>` form, or a raw file holding the literal a
 * number of times other than one per withheld entry (the two cases below drive this rule).
 */
function unresolvedCellFindings({ text, catalogue, moduleArrays, withheld }) {
  const findings = [];
  for (const [module, tools] of Object.entries(moduleArrays)) {
    for (const tool of tools) {
      if (JSON.stringify(tool).includes('unresolved:')) findings.push(`${module}/${tool.function.name}: a tool offered to a model holds an unresolved cell`);
    }
  }
  for (const entry of catalogue) {
    const key = `${entry.module}/${entry.name}`;
    if (withheld.has(key)) {
      if (!isUnresolvedSchemaCell(entry.tableHash)) findings.push(`${key}: a withheld entry's tableHash must be the documented unresolved:<reason> form`);
      continue;
    }
    if (JSON.stringify(entry).includes('unresolved:')) findings.push(`${key}: only a withheld entry may carry the unresolved cell`);
  }
  const occurrences = text.split('unresolved:').length - 1;
  if (occurrences !== withheld.size) {
    findings.push(`the file holds the literal unresolved: ${occurrences} time(s); expected one per withheld entry (${withheld.size})`);
  }
  return findings;
}

test('the file header pins the same fork rev and the same mechanical block as genoffice-tools.md', () => {
  assert.ok(block, 'the extract block markers are present in genoffice-tools.md');
  assert.equal(file.header.kind, 'genoffice-tool-schemas');
  assert.equal(file.header.version, 1);
  assert.equal(file.header.rev, committed.rev, 'header rev = the extract block rev');
  // the extractor's stdout is the block lines plus a final newline: hash it exactly as `--emit-schemas` did
  assert.equal(file.header.mechanicalBlockSha256, sha256Hex(`${block.join('\n')}\n`));
});

test('the file lists exactly the tool names of the committed extract block, module by module', () => {
  const fromBlock = namesByModule(committed.rows);
  const fromCatalogue = namesByModule(file.catalogue);
  assert.deepEqual(fromCatalogue, fromBlock);
  for (const module of MODULES) {
    assert.equal(file.header.counts[module], fromBlock[module].length, `${module}: header count`);
  }
  // one catalogue entry per table row (agent-core rows included), and each row's own hash cell is carried
  assert.equal(file.catalogue.length, committed.rows.length);
  // the rows the file is allowed to withhold are the block's documented unresolved ones, and no others
  assert.deepEqual(unresolvedKeys(committed.rows), [...UNRESOLVED_SCHEMA_TOOLS].sort(), 'the block carries exactly the reviewed unresolved rows');
  const hashes = new Map(committed.rows.map((r) => [`${r.module}|${r.tool}|${r.source}`, r.hash]));
  for (const entry of file.catalogue) {
    assert.equal(entry.tableHash, hashes.get(`${entry.module}|${entry.name}|${entry.source}`), `${entry.module}/${entry.name}`);
  }
});

test('every tool with a schema is offered whole; the withheld and partial ones are exactly the reviewed ones', () => {
  const withheld = new Set(UNRESOLVED_SCHEMA_TOOLS);
  for (const entry of file.catalogue) {
    const key = `${entry.module}/${entry.name}`;
    if (withheld.has(key)) {
      // The block cell is `unresolved:<reason>`: there is no schema to offer, so the file records the tool and why.
      assert.equal(entry.offered, false, `${key} must not be offered without a schema`);
      assert.equal(entry.schemaComplete, false, `${key}: ${entry.reason}`);
      assert.equal(entry.inputSchemaSha256, null, `${key}: a withheld tool embeds no schema`);
      assert.ok(typeof entry.reason === 'string' && entry.reason.length > 0, `${key}: a withheld tool says why`);
      assert.ok(isUnresolvedSchemaCell(entry.tableHash), `${key}: the block cell is the documented unresolved form`);
      continue;
    }
    assert.equal(entry.offered, true, `${key} is not offered: ${entry.reason}`);
    assert.equal(entry.schemaComplete, true, `${key}: ${entry.reason}`);
  }
  for (const module of MODULES) {
    assert.deepEqual(
      file[module].map((t) => t.function.name).sort(),
      offeredNamesByModule(committed.rows)[module],
      `${module}: the module array offers every table row whose schema resolved`,
    );
    for (const tool of file[module]) {
      const { name, description, parameters } = tool.function;
      assert.equal(tool.type, 'function');
      assert.deepEqual(Object.keys(tool), ['type', 'function'], `${module}/${name}: nothing but the schema is sent to a model`);
      assert.ok(typeof description === 'string' && description.length > 0, `${module}/${name}: description`);
      assert.ok(parameters && parameters.type === 'object', `${module}/${name}: parameters`);
      const entry = file.catalogue.find((e) => e.module === module && e.name === name);
      assert.equal(sha256Hex(canonical(parameters)), entry.inputSchemaSha256, `${module}/${name}: schema hash`);
    }
  }
  // RBD-7 / RBD-8: the block's own hash cell is the witness of the schema the file ships, so a schema body
  // edited by hand — with its stored hash updated to match — fails here. The single documented divergence is
  // docs/set_page_setup: its block cell pins the default evaluator's `+`-misread schema while the emit pass
  // reads it whole (report-w10 residual 1). A withheld row has no schema to witness. Any second divergent row fails.
  for (const entry of file.catalogue) {
    const key = `${entry.module}/${entry.name}`;
    if (key === 'docs/set_page_setup' || withheld.has(key)) continue;
    assert.equal(entry.inputSchemaSha256, entry.tableHash, `${key}: the block cell must witness the embedded schema`);
  }
  const partial = file.catalogue.filter((e) => !e.descriptionComplete).map((e) => `${e.module}/${e.name}`);
  assert.deepEqual(partial.sort(), PARTIAL_DESCRIPTION_TOOLS);
  for (const key of PARTIAL_DESCRIPTION_TOOLS) {
    const [module, name] = key.split('/');
    const tool = file[module].find((t) => t.function.name === name);
    assert.ok(tool.function.description.includes(RUNTIME_MARK), `${key}: the runtime marker stands where the code ran`);
  }
  // no other description carries the marker
  for (const module of MODULES) {
    for (const tool of file[module]) {
      if (PARTIAL_DESCRIPTION_TOOLS.includes(`${module}/${tool.function.name}`)) continue;
      assert.ok(!tool.function.description.includes(RUNTIME_MARK), `${module}/${tool.function.name}`);
    }
  }
  for (const module of ['docs', 'markdown']) {
    const entry = file.catalogue.find((e) => e.module === module && e.name === 'generate_mindmap');
    assert.ok(entry, `${module}/generate_mindmap is in the catalogue`);
    assert.equal(entry.offered, true, `${module}/generate_mindmap is offered after G6-09d`);
    assert.equal(entry.schemaComplete, true, `${module}/generate_mindmap schemaComplete after G6-09d`);
    assert.equal(entry.inputSchemaSha256, MINDMAP_SCHEMA_SHA256, `${module}/generate_mindmap schema hash`);
    assert.equal(entry.tableHash, MINDMAP_SCHEMA_SHA256, `${module}/generate_mindmap tableHash`);
    assert.ok(file[module].some((t) => t.function.name === 'generate_mindmap'), `${module} offers generate_mindmap`);
  }
  // The withheld rows are the only place the unresolved cell may appear, in the JSON and in the raw file alike; the
  // negative cases below drive that rule.
  assert.deepEqual(
    unresolvedCellFindings({ text: schemaBytes.toString('utf8'), catalogue: file.catalogue, moduleArrays: moduleArraysOf(file), withheld }),
    [],
    'the unresolved cell lives only in the withheld entries\' tableHash',
  );
});

test("the unresolved cell anywhere but a withheld entry's tableHash fails: a third entry, or the literal in a module array", () => {
  const fixtureWithheld = ['docs/generate_mindmap', 'markdown/generate_mindmap'];
  const withheld = new Set(fixtureWithheld);
  const cell = 'unresolved:identifier:depth';
  const entry = (key, tableHash) => ({ module: key.split('/')[0], name: key.split('/')[1], tableHash });
  const withheldEntries = fixtureWithheld.map((key) => entry(key, cell));
  const text = (entries) => JSON.stringify({ header: {}, catalogue: entries, docs: [], markdown: [] });
  const clean = { text: text(withheldEntries), catalogue: withheldEntries, moduleArrays: { docs: [], markdown: [] }, withheld };
  assert.deepEqual(unresolvedCellFindings(clean), [], 'the withheld rows alone are clean');
  // a third row the block does not carry: it is not withheld, and the file now holds the literal three times
  const third = entry('docs/third_tool', cell);
  assert.deepEqual(unresolvedCellFindings({ ...clean, text: text([...withheldEntries, third]), catalogue: [...withheldEntries, third] }), [
    'docs/third_tool: only a withheld entry may carry the unresolved cell',
    'the file holds the literal unresolved: 3 time(s); expected one per withheld entry (2)',
  ]);
  // the literal inside a tool a model is offered
  const offered = { type: 'function', function: { name: 'read_blocks', description: cell, parameters: { type: 'object' } } };
  assert.deepEqual(unresolvedCellFindings({ ...clean, moduleArrays: { docs: [offered], markdown: [] } }), [
    'docs/read_blocks: a tool offered to a model holds an unresolved cell',
  ]);
});

test('holdout-backend loads the file with --tool-schemas semantics and offers every mapped tool a real schema', () => {
  const catalogue = toolCatalogue(file);
  const surface = toolSurface(catalogue, { fileSha256: sha256Hex(schemaBytes), frameTotals: frameToolCounts() });
  for (const module of MODULES) {
    const mapped = Object.keys(TOOL_OPS[module]).sort();
    const offered = catalogue[module];
    assert.deepEqual(offered.map((t) => t.function.name).sort(), mapped, `${module}: the harness offers every mapped tool`);
    assert.match(surface[module].source, /^file:[0-9a-f]{64}$/, `${module}: no tool is name-only or from the dev set`);
    assert.equal(surface[module].offered, mapped.length);
    assert.equal(surface[module].frameTotal, file.header.counts[module]);
    // the offered tool is the file's own object: a real schema, never the name-only stand-in
    for (const tool of offered) {
      const own = file[module].find((t) => t.function.name === tool.function.name);
      assert.ok(own, `${module}/${tool.function.name} is in the file`);
      assert.deepEqual(tool, own);
      assert.notEqual(tool.function.description, `Tool ${tool.function.name} of the ${module} module of the open document.`);
    }
    // what the file describes beyond the mapping is reported, not offered (mapping more is g6-ai_server's, not this file's)
    assert.equal(surface[module].droppedFromFile.length, file[module].length - mapped.length);
  }
  // end to end for one case shape: the tools a case is offered come from the file
  const caseDoc = { fixtures: [{ id: 'fx-md-brief' }], tools: { required: [] } };
  const tools = offeredTools(caseDoc, catalogue);
  assert.deepEqual(tools.map((t) => t.function.name).sort(), Object.keys(TOOL_OPS.markdown).sort());
});

// G7-12-SCHEMA step 3 (UNI-1964): the four formats C6 ran name-only (slides / pdf / markdown / html) get the file's
// own schemas once the runner hands the file over, so the surface a run records has no name-only module and the
// required keys the holdout cases rely on (contract-draft.md "Required keys in the file") are actually there. The
// per-tool "the offered tool is the file's own object" identity for all six modules is pinned by the test above; this
// pins the negative list the report reads (`conditions.scoped.nameOnly.modules`) and the case-required keys.
const CASE_REQUIRED_KEYS = {
  slides: { read_slide: ['slideIndex'], apply_ops: ['ops'] },
  pdf: { read_pages: ['start'], search_text: ['query'], edit_text: ['page', 'old_text', 'new_text'], edit_block: ['page', 'paragraph_text', 'new_text'] },
  markdown: { read_blocks: ['startIndex', 'endIndex'], apply_ops: ['ops'] },
  html: { apply_ops: ['ops'] },
};

test('the committed file leaves no name-only module and carries the required keys of the four formats', () => {
  const catalogue = toolCatalogue(file);
  const surface = toolSurface(catalogue, { fileSha256: sha256Hex(schemaBytes), frameTotals: frameToolCounts() });
  assert.deepEqual(
    Object.entries(surface).filter(([, v]) => v.source === 'name-only').map(([m]) => m),
    [],
    'no module of the six is name-only once the file is handed over',
  );
  for (const module of Object.keys(CASE_REQUIRED_KEYS)) assert.match(surface[module].source, /^file:[0-9a-f]{64}$/, `${module}: the surface is the file's own`);
  for (const [module, tools] of Object.entries(CASE_REQUIRED_KEYS)) {
    for (const [name, keys] of Object.entries(tools)) {
      const own = file[module].find((t) => t.function.name === name);
      assert.ok(own, `${module}/${name} is in the file`);
      const required = own.function.parameters.required ?? [];
      for (const key of keys) assert.ok(required.includes(key), `${module}/${name}: required key "${key}" is present (required: ${required.join(', ') || 'none'})`);
    }
  }
});
